# area: generics_variance
# hypothesis: Passing a Handler[float] through an unannotated gradual parameter hides the invariance violation from mypy, so the int-only sink is installed silently and then fails at runtime on a float.
from typing import Protocol, reveal_type


class Sink[T](Protocol):
    def __call__(self, value: T) -> None: ...


class Handler[T]:
    def __init__(self, sink: Sink[T]) -> None:
        self.sink: Sink[T] = sink

    def fire(self, value: T) -> None:
        self.sink(value)


def set_int_sink(h: Handler[int]) -> None:
    h.sink = lambda x: print('bits', x.bit_length())


def misuse(h):  # gradual: unannotated parameter, so the call below is not checked
    set_int_sink(h)


hf = Handler[float](lambda x: print('float', x))
reveal_type(hf)
hf.fire(2.5)

try:
    misuse(hf)
    hf.fire(1.5)  # runtime: AttributeError, float has no bit_length
except AttributeError as e:
    print('caught', type(e).__name__)
